    font-size: calc(1.04167vw * var(--ec-zoom));
  }
}
@media (width >= 1024px) {
  .small {
    font-size: calc(1.04167vw * var(--ec-zoom));
  }
}

p {
  font-family: Inter, sans-serif;
}
@media (width <= 739px) {
  p {
    font-size: 14px;
  }
}
@media (width >= 740px) and (width <= 1023px) {
  p {
    font-size: 16px;
  }
}
@media (width >= 1024px) {
  p {
    font-size: 18px;
  }
}
